def _dongu_bul(kalan_paketler: set[str], komsuluk: dict[str, list[str]], 
                deps: dict[str, list[str]]) -> list[str]:
    """Kalan paketler içinde bir döngü bulur ve alfabetik en küçüğüyle başlayan liste döndürür."""
    # Kalan paketler için alt grafiği oluştur (sadece kalan paketler arası kenarlar)
    alt_komsuluk = defaultdict(list)
    for paket in kalan_paketler:
        for bagimli in set(deps.get(paket, [])):
            if bagimli in kalan_paketler:
                alt_komsuluk[bagimli].append(paket)

    # DFS ile döngü bul
    ziyaret_edildi = set()
    yigin = set()
    ebeveyn = {}

    def dfs(dugum: str) -> list[str] | None:
        ziyaret_edildi.add(dugum)
        yigin.add(dugum)

        for komsu in alt_komsuluk[dugum]:
            if komsu not in ziyaret_edildi:
                ebeveyn[komsu] = dugum
                sonuc = dfs(komsu)
                if sonuc:
                    return sonuc
            elif komsu in yigin:
                # Döngü bulundu - geriye doğru izle
                dongu = [komsu]
                g = dugum
                while g != komsu:
                    dongu.append(g)
                    g = ebeveyn[g]
                dongu.append(komsu)
                dongu.reverse()  # Başlangıçtan sona doğru
                return dongu

        yigin.remove(dugum)
        return None

    # Alfabetik sırayla başla ki en küçük paketle başlayan döngü bulunsun
    for paket in sorted(kalan_paketler):
        if paket not in ziyaret_edildi:
            dongu = dfs(paket)
            if dongu:
                # Döngüyü alfabetik en küçük elemanla başlatacak şekilde döndür
                min_indeks = min(range(len(dongu) - 1), key=lambda i: dongu[i])
                dongu = dongu[min_indeks:-1] + dongu[:min_indeks] + [dongu[min_indeks]]
                return dongu[:-1]  # Son eleman (tekrar) çıkar

    # Fallback (olmamalı)
    return sorted(kalan_paketler)[:1]

