from bagimlilik import kurulum_sirasi, DonguHatasi

# Test 5: Döngü - a->b->c->a (a b'ye bağlı, b c'ye bağlı, c a'ya bağlı)
print('Test 5: Döngü a->b->c->a')
deps5 = {'a': ['b'], 'b': ['c'], 'c': ['a']}
try:
    kurulum_sirasi(deps5)
except DonguHatasi as e:
    print(f'DonguHatasi: dongu={e.dongu}')  # ['a', 'b', 'c'] olmalı (a->b->c->a)
print()

